def seed_approved_zips(apps, schema_editor):
    ServiceArea = apps.get_model('portal', 'ServiceArea')
    database = schema_editor.connection.alias
    for code in INITIAL_ZIPS:
        area, created = ServiceArea.objects.using(database).get_or_create(
            postal_code=code, defaults={'name': f'Approved ZIP {code}', 'active': True, 'auto_enrollment': True})
        if not created:
            # Preserve existing names and inactive-service decisions.
            area.auto_enrollment = True
            area.save(using=database, update_fields=['auto_enrollment'])


